+                @Override
+                public Void call(Object... args) {
+                    task.dependsOn(defaultDistro);
+                    registerDistributionInputs(task, defaultDistro);
+
+                    nonInputSystemProperties.systemProperty(
+                        DEFAULT_DISTRIBUTION_SYSPROP,
