+        assertMultiGetResponse(multiGetRequestBuilder.get(), numDocs);
+        assertThat(processor.getTotalBytesInFlight(), equalTo(0L));
+    }
+
+    public void testBulkProcessor2WaitOnClose() throws Exception {
