+            }
+        }
+    }
+
+    // this loop should auto-vectorize
+    private void mul(long[] arr, long m) {
+        for (int i = 0; i < blockSize; ++i) {
+            arr[i] *= m;
+        }
+    }
+
+    // this loop should auto-vectorize
+    private void add(long[] arr, long min) {
+        for (int i = 0; i < blockSize; ++i) {
+            arr[i] += min;
+        }
+    }
+
+    private void deltaDecode(long[] arr) {
+        for (int i = 1; i < blockSize; ++i) {
+            arr[i] += arr[i - 1];
+        }
+    }
+}

